parameters.jsCode:
// n8n Code node (JavaScript)
// Input: Gemini Create Story output
// Output: { ok, title, description, narration_text }

function pickText($json) {
  const candidates = [
    $json?.content?.parts?.[0]?.text,
    $json?.content?.parts?.[0],
    $json?.text,
    $json?.output,
    $json?.response?.generations?.[0]?.[0]?.text,
  ];
  for (const c of candidates) {
    if (typeof c === 'string' && c.trim()) return c;
  }
  return '';
}

function stripCodeFence(s) {
  return String(s || '')
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();
}

function normalizeSmartQuotes(s) {
  return s
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'");
}

function extractJsonObject(s) {
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) {
    throw new Error('no_json_object_braces_found');
  }
  return s.slice(start, end + 1);
}

try {
  let raw = pickText($json);
  if (!raw) {
    return [{ json: { ok: false, error: 'no_text_found', raw_preview: '' } }];
  }

  let cleaned = stripCodeFence(raw);
  cleaned = extractJsonObject(cleaned);
  cleaned = normalizeSmartQuotes(cleaned);

  const obj = JSON.parse(cleaned);

  const ok =
    obj &&
    typeof obj === 'object' &&
    typeof obj.title === 'string' &&
    typeof obj.description === 'string' &&
    typeof obj.narration_text === 'string';

  if (!ok) {
    return [{
      json: {
        ok: false,
        error: 'parsed_but_schema_invalid',
        parsed_keys: obj ? Object.keys(obj) : null,
        raw_preview: cleaned.slice(0, 500),
      }
    }];
  }

  return [{
    json: {
      ok: true,
      title: obj.title,
      description: obj.description,
      narration_text: obj.narration_text,
      char_count_ko: obj.narration_text.length,
    }
  }];

} catch (e) {
  const raw = pickText($json);
  return [{
    json: {
      ok: false,
      error: 'create_story_json_parse_failed',
      message: String(e?.message || e),
      raw_preview: String(raw || '').slice(0, 500),
    }
  }];
}

function extractJsonCandidate(text) {
  if (!text || typeof text !== 'string') return null;

  const m1 = text.match(/```json\s*([\s\S]*?)```/i);
  if (m1 && m1[1]) return m1[1].trim();

  const m2 = text.match(/```\s*([\s\S]*?)```/);
  if (m2 && m2[1]) return m2[1].trim();

  return text.trim();
}

function safeJsonParse(text) {
  const cand = extractJsonCandidate(text);
  if (!cand) return { ok: false, error: "NO_TEXT" };
  try {
    return JSON.parse(cand);
  } catch (e) {
    return { ok: false, error: "JSON_PARSE_FAILED", detail: String(e), raw: cand.slice(0, 1200) };
  }
}

const input = items[0].json;
const videos = input.videos || [];

const outVideos = videos.map((v, i) => {
  const meta = v.meta || {};
  const va = v.videoAnalysis || {};
  const parsed = safeJsonParse(va.text);

  // ✅ 형식 필드만 남기기(content 제거 전제)
  let slimParsed = null;
  if (parsed && parsed.ok === true) {
    slimParsed = {
      ok: true,
      video_index: parsed.video_index,
      hook: parsed.hook || {},
      structure: parsed.structure || {},
      style_tone: parsed.style_tone || {},
      retention: parsed.retention || {},
      quotes: parsed.quotes || { items: [] },
    };
  } else {
    slimParsed = { ok: false, parse_error: parsed };
  }

  return {
    meta: {
      title: meta.title || "",
      channel: meta.channel || "",
    },
    url: v.url || "",
    parsed: slimParsed,
    // 원본 text는 필요하면 유지, 아니면 제거 가능
    // videoAnalysisText: (va.text || "").slice(0, 2000),
  };
});

return [{ json: { ok: input.ok, count: input.count, videos: outVideos } }];

// 모든 행 데이터($input.all())에서 'title' 값만 뽑아서 배열로 만듦
const allTitles = $input.all().map(item => item.json.title);

return {
  json: {
    titles: allTitles // 결과: ["제목1", "제목2", "제목3", ...]
  }
};

function pickGeminiText(itemJson) {
  const t1 = itemJson?.content?.parts?.[0]?.text;
  if (typeof t1 === 'string' && t1.trim()) return t1.trim();

  const t2 = itemJson?.text;
  if (typeof t2 === 'string' && t2.trim()) return t2.trim();

  return '';
}

function stripFence(s) {
  return String(s || '')
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();
}

function extractFirstJsonObject(s) {
  const str = String(s || '');
  const start = str.indexOf('{');
  const end = str.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) {
    throw new Error('no_json_object_found');
  }
  return str.slice(start, end + 1);
}

function normalizeSpace(s) {
  return String(s || '').replace(/\s+/g, ' ').trim();
}

function ensureVeoFooter(prompt) {
  const footer =
`maintain the exact scene composition from the input image
preserve subject placement and background layout
no scene reconstruction
no new objects introduced
static camera
stable background
sharp throughout the full clip
no text no subtitles no logos no UI
safe non violent non sexual
cinematic documentary b-roll style`;

  const p = String(prompt || '').trim();
  if (!p) return footer;

  if (
    p.includes('maintain the exact scene composition from the input image') &&
    p.includes('preserve subject placement and background layout') &&
    p.includes('no scene reconstruction') &&
    p.includes('static camera') &&
    p.includes('stable background')
  ) {
    return p;
  }

  return `${p}\n${footer}`.trim();
}

try {
  const first = $input.first();
  const raw = pickGeminiText(first?.json || {});
  if (!raw) throw new Error('no_text_found');

  const obj = JSON.parse(extractFirstJsonObject(stripFence(raw)));

  if (!obj || !Array.isArray(obj.shots)) {
    throw new Error('shots_not_array');
  }

  const aspect_ratio = String(
    $items('Get Data')?.[0]?.json?.Ratio ?? '9:16'
  ).trim();

  const reference_image_url = String(
    $items('Reference Image')?.[0]?.json?.reference_image_url ?? ''
  ).trim();

  if (!reference_image_url) {
    throw new Error('reference_image_url_missing');
  }

  // Scene Apply Code 결과를 shot_index 기준으로 매핑
  const appliedItems = $items('Scene Apply Code');
  const mergedScriptMap = new Map();

  for (const item of appliedItems) {
    const idx = Number(item?.json?.shot_index);
    if (Number.isFinite(idx)) {
      mergedScriptMap.set(
        idx,
        String(item?.json?.merged_script || item?.json?.script || '').trim()
      );
    }
  }

  return obj.shots.map((shot, i) => {
    const rawShotIndex = Number(shot?.shot_index);
    const shot_index = Number.isFinite(rawShotIndex) ? rawShotIndex : i;

    const start_sec = Number(shot?.start_sec);
    const duration = Number(shot?.duration);

    const script = String(shot?.script || '').trim();
    const merged_script = String(
      mergedScriptMap.get(shot_index) || script
    ).trim();

    const image_prompt_final = normalizeSpace(String(shot?.image_prompt || ''));
    const video_prompt_final = ensureVeoFooter(String(shot?.video_prompt || ''));

    return {
      json: {
        ok: true,

        // shot identity
        shot_index,
        shot_name: `shot_${shot_index}`,

        // timing
        aspect_ratio,
        start_sec: Number.isFinite(start_sec) ? start_sec : null,
        duration: Number.isFinite(duration) ? duration : null,

        // text
        script,
        merged_script,

        // prompts
        image_prompt_final,
        video_prompt_final,

        // style reference URL 하나만 유지
        imageUrls: [reference_image_url]
      }
    };
  });

} catch (e) {
  const first = $input.first();
  const raw = pickGeminiText(first?.json || {});

  return [{
    json: {
      ok: false,
      error: String(e?.message || e),
      raw_preview: String(raw || '').slice(0, 1200),
    }
  }];
}

const items = $input.all();

return items.map((it, i) => {
  const d = it.json?.body?.data || it.json?.data || {};

  let url = null;
  try {
    const rj = d?.resultJson;
    const obj = (typeof rj === 'string') ? JSON.parse(rj) : rj;
    url = obj?.resultUrls?.[0] || null;
  } catch (e) {}

  url = String(url || '').split('\n')[0].split('\r')[0].trim();

  const state = String(d?.state || '').toLowerCase();
  // Treat HTTP 5xx responses from Grok Check as failed (triggers retry path)
  const httpStatus = it.json?.statusCode || it.json?.status || 200;
  const serverError = httpStatus >= 500;

  const failed = state === 'failed' || state === 'fail' || !!d?.failCode || serverError;
  const done = state === 'success' && /^https?:\/\//i.test(url);
  const poll_count = (it.json?.poll_count || 0) + 1;
  const retry_count = it.json?.retry_count || 0;

  return {
    json: {
      ...it.json,
      taskId: d?.taskId ?? it.json?.taskId ?? null,
      state: d?.state ?? null,
      done,
      failed,
      poll_count,
      retry_count,
      video_url: url
    },
    pairedItem: { item: i }
  };
});

