parameters.jsCode:
// ===== FFmpeg Input Builder (UNIFIED: supports video_#.mp4 OR scene_#.mp4) =====
const items = $input.all();

const DEFAULT_BUCKET = "n8n_best_automation";

let folder = "";
let audioPath = "";
let videoPaths = [];

function getFolderFromName(name) {
  const parts = String(name || "").split("/");
  return parts[0] || "";
}

function getIndexFromVideoName(name) {
  const s = String(name || "");
  let m = s.match(/(?:^|\/)video_(\d+)\.mp4$/i);
  if (!m) m = s.match(/(?:^|\/)scene_(\d+)\.mp4$/i);
  if (!m) return null;

  const n = parseInt(m[1], 10);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function isAudioName(name) {
  return /(?:^|\/)audio(\.[a-z0-9]+)?$/i.test(String(name || ""));
}

function isAudioByContentType(j) {
  const ct = String(j?.contentType || "");
  return ct.startsWith("audio/");
}

// 1) 입력 아이템(storage#object)에서 video/audio 분류
for (const item of items) {
  const j = item.json || {};
  const name = j.name;
  const bucket = j.bucket || DEFAULT_BUCKET;
  if (!name) continue;

  if (!folder) folder = getFolderFromName(name);

  const vidIdx = getIndexFromVideoName(name);
  if (vidIdx) {
    videoPaths.push({
      index: vidIdx,
      path: `gs://${bucket}/${name}`,
    });
    continue;
  }

  if (!audioPath && (isAudioByContentType(j) || isAudioName(name))) {
    audioPath = `gs://${bucket}/${name}`;
  }
}

// 2) 비디오 정렬
videoPaths.sort((a, b) => a.index - b.index);
const sortedVideos = videoPaths.map(v => v.path);

// 3) durations_sec: Script Code(우선) → 없으면 Image Code fallback
function buildDurationsPairsFromNode(nodeItems) {
  return (nodeItems || []).map((it, i) => {
    const j = it.json || {};

    const raw =
      (j.shot_no ??
       j.index ??
       (j.shot_index !== undefined ? (Number(j.shot_index) + 1) : (i + 1)));

    const idx = parseInt(String(raw).trim(), 10);

    return {
      index: Number.isFinite(idx) && idx > 0 ? idx : (i + 1),
      duration: Number(j.duration) || 4,
    };
  }).sort((a, b) => a.index - b.index);
}

let durationsPairs = [];

try {
  durationsPairs = buildDurationsPairsFromNode($("Script Code").all());
} catch (e) {
  durationsPairs = [];
}

if (durationsPairs.length === 0) {
  try {
    durationsPairs = buildDurationsPairsFromNode($("Image Code").all());
  } catch (e) {
    durationsPairs = [];
  }
}

const durations_sec = durationsPairs.map(x => x.duration);

// 4) 검증
if (!folder) {
  throw new Error("ID(folder)를 찾지 못했습니다. 입력 아이템 json.name이 'ID/...' 형태인지 확인하세요.");
}
if (sortedVideos.length === 0) {
  throw new Error("비디오를 찾지 못했습니다. name이 'ID/video_#.mp4' 또는 'ID/scene_#.mp4' 형태인지 확인하세요.");
}
if (!audioPath) {
  throw new Error("오디오를 찾지 못했습니다. name이 'ID/audio(.확장자)' 형태인지, 또는 contentType이 audio/*인지 확인하세요.");
}

// 5) 개수 맞추기
const n = Math.min(sortedVideos.length, durations_sec.length);
const videosFinal = sortedVideos.slice(0, n);
const durationsFinal = durations_sec.slice(0, n);

const warn = {
  inputItems: items.length,
  videosFound: sortedVideos.length,
  durationsFound: durations_sec.length,
  used: n,
};

return [{
  json: {
    mode: "grok",
    audio: audioPath,
    videos: videosFinal,
    durations_sec: durationsFinal,
    fps: 30,
    output: `gs://${DEFAULT_BUCKET}/${folder}/shorts_final.mp4`,
    warn,
  }
}];

const items = $input.all();
const productionId = String($('Get Data').first().json.ID || '').trim();
const scriptItems = $items('Script Code');

return items.map((it, i) => {
  const shot_index = Number(
    it.json?.shot_index ??
    it.json?.global_scene_index ??
    i
  );

  if (!Number.isFinite(shot_index)) {
    throw new Error(`Invalid shot_index at item ${i}`);
  }

  const matched = scriptItems.find(s => Number(s.json?.shot_index) === shot_index);

  if (!matched) {
    throw new Error(`No Script Code item matched for shot_index=${shot_index}`);
  }

  let image_url = '';

  try {
    // 1) resultJson 우선
    const rj =
      it.json?.data?.resultJson ??
      it.json?.body?.data?.resultJson ??
      it.json?.resultJson;

    if (rj) {
      const obj = (typeof rj === 'string') ? JSON.parse(rj) : rj;
      image_url = String(obj?.resultUrls?.[0] || '').trim();
    }

    // 2) fallback: response.resultUrls
    if (!image_url) {
      image_url = String(
        it.json?.data?.response?.resultUrls?.[0] ??
        it.json?.body?.data?.response?.resultUrls?.[0] ??
        ''
      ).trim();
    }
  } catch (e) {}

  if (!/^https?:\/\//i.test(image_url)) {
    throw new Error(`Invalid image_url for shot_index=${shot_index}`);
  }

  const scene_number = shot_index + 1;
  const gcs_object_name = `${productionId}(Production)/scene_${scene_number}.mp4`;

  return {
    json: {
      ...it.json,
      shot_index,
      scene_number,
      gcs_object_name,
      image_url,
      video_prompt_final: String(matched.json?.video_prompt_final || '').trim(),
      script: String(matched.json?.script || '').trim(),
      duration: matched.json?.duration ?? null,
      start_sec: matched.json?.start_sec ?? null,
      aspect_ratio: String(matched.json?.aspect_ratio || '9:16').trim()
    }
  };
});

function pickGeminiText(itemJson) {
  const t1 = itemJson?.content?.parts?.[0]?.text;
  if (typeof t1 === 'string' && t1.trim()) return t1.trim();

  const t2 = itemJson?.text;
  if (typeof t2 === 'string' && t2.trim()) return t2.trim();

  return '';
}

function stripFence(s) {
  return String(s || '')
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();
}

function extractFirstJsonObject(s) {
  const str = String(s || '');
  const start = str.indexOf('{');
  const end = str.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) {
    throw new Error('no_json_object_found');
  }
  return str.slice(start, end + 1);
}

const srtRaw = pickGeminiText($items("SRT")[0].json);
if (!srtRaw) throw new Error("srt_raw_missing");

const groupsRaw = pickGeminiText($input.first().json);
if (!groupsRaw) throw new Error("groups_raw_missing");

const srtObj = JSON.parse(extractFirstJsonObject(stripFence(srtRaw)));
const groupObj = JSON.parse(extractFirstJsonObject(stripFence(groupsRaw)));

if (!Array.isArray(srtObj.shots)) throw new Error("shots_not_array");
if (!Array.isArray(groupObj.groups)) throw new Error("groups_not_array");

const shots = srtObj.shots;
const groups = groupObj.groups;

// 기본값: merged_script = 자기 script
const shotMap = shots.map((shot, i) => {
  const shot_index = Number(shot?.shot_index);
  return {
    shot_index: Number.isFinite(shot_index) ? shot_index : i,
    start_sec: Number(shot?.start_sec),
    duration: Number(shot?.duration),
    script: String(shot?.script || "").trim(),
    merged_script: String(shot?.script || "").trim()
  };
});

// 그룹 적용
for (const g of groups) {
  const start = Number(g?.shot_start_index);
  const end = Number(g?.shot_end_index);
  const merged = String(g?.merged_script || "").trim();

  if (!Number.isFinite(start) || !Number.isFinite(end) || !merged) continue;

  for (const shot of shotMap) {
    if (shot.shot_index >= start && shot.shot_index <= end) {
      shot.merged_script = merged;
    }
  }
}

// item 1개만 출력
return [
  {
    json: {
      shots: shotMap.map(shot => ({
        shot_index: shot.shot_index,
        start_sec: Number.isFinite(shot.start_sec) ? shot.start_sec : null,
        duration: Number.isFinite(shot.duration) ? shot.duration : null,
        script: shot.script,
        merged_script: shot.merged_script
      }))
    }
  }
];

return $input.all().map((it, i) => ({
  json: {
    ...it.json,
    retry_count: (it.json.retry_count || 0) + 1,
    taskId: null,
    done: false,
    failed: false,
    poll_count: 0
  },
  pairedItem: { item: i }
}));

